package com.coffeeshop.service;import com.coffeeshop.model.NotificationModels;import com.coffeeshop.repository.NotificationRepository;import org.junit.jupiter.api.Test;import java.time.LocalDateTime;import java.util.*;import static org.junit.jupiter.api.Assertions.*;class NotificationServiceTest{private final Stub repo=new Stub();private final NotificationService service=new NotificationService(repo);@Test void requiresUserForListing(){assertThrows(IllegalArgumentException.class,()->service.notifications(0,null));service.notifications(2,false);assertEquals(2,repo.user);}@Test void marksUnreadOnly(){var unread=n(false);service.markRead(unread,3);assertEquals(1,repo.marked);service.markRead(n(true),3);assertEquals(1,repo.marked);}@Test void lowStockGenerationRequiresAuthorization(){assertThrows(SecurityException.class,()->service.generateLowStock(false));assertEquals(4,service.generateLowStock(true));}private static NotificationModels.Notification n(boolean read){return new NotificationModels.Notification(1,"INFO","T","M",null,null,read,read?LocalDateTime.now():null,null,LocalDateTime.now().minusMinutes(1),new byte[]{1});}private static final class Stub implements NotificationRepository{long user;int marked;public List<NotificationModels.Notification>find(long u,Boolean r){user=u;return List.of();}public void markRead(long id,long u,byte[]v){marked++;}public int generateLowStockAlerts(){return 4;}}}
